<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import * as api from '../services/meetings'

const tab=ref('config'), configTab=ref('rooms'), loading=ref(false), error=ref(''), notice=ref(''), modal=ref('')
const form=reactive({}), rooms=ref([]), equipment=ref([]), openings=ref([]), prices=ref([]), services=ref([])
const bookings=ref([]), tasks=ref([]), rules=ref([]), usages=ref([]), logs=ref([]), overview=ref(null), utilization=ref([]), serviceSales=ref([])
const today=date(new Date()), start=ref(date(new Date(Date.now()-29*86400000))), end=ref(date(new Date(Date.now()+30*86400000)))
const statusFilter=ref(''), typeFilter=ref(''), roomFilter=ref(''), keyword=ref(''), verifyCode=ref(''), deviceNo=ref('MEETING-DESK-01')
const dayText=['','周一','周二','周三','周四','周五','周六','周日']
const statusText={DRAFT:'草稿',PENDING_PAYMENT:'待支付',PENDING_APPROVAL:'待审批',PAID:'已支付',APPROVED:'已批准',REJECTED:'已驳回',VERIFIED:'使用中',COMPLETED:'已完成',CANCELLED:'已取消',PENDING:'待处理',CHECKED_IN:'已入场',REVOKED:'已撤销',ACTIVE:'启用',INACTIVE:'停用'}
const configRows=computed(()=>({rooms:rooms.value,equipment:equipment.value,openings:openings.value,prices:prices.value,services:services.value}[configTab.value]||[]))
const cards=computed(()=>overview.value?[['预订总量',overview.value.bookingCount,`待处理 ${overview.value.pendingCount}`],['实收金额',money(overview.value.paidAmountCent),`报价 ${money(overview.value.quotedAmountCent)}`],['已完成',overview.value.completedCount,`已核销 ${overview.value.verificationCount} 次`],['参会人次',overview.value.attendeeCount,`配套服务 ${money(overview.value.serviceAmountCent)}`],['会议室利用率',`${overview.value.utilizationRate}%`,`${overview.value.occupiedMinutes}/${overview.value.capacityMinutes} 分钟`]]:[])

async function run(fn,msg=''){try{loading.value=true;error.value='';await fn();if(msg)notice.value=msg}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadConfig(){await run(async()=>{[rooms.value,equipment.value,openings.value,prices.value,services.value]=await Promise.all([api.getMeetingRooms(),api.getMeetingEquipment(),api.getMeetingOpeningRules(),api.getMeetingPriceRules(),api.getMeetingServices()])})}
const query=()=>({startDate:start.value,endDate:end.value,roomId:roomFilter.value||undefined,status:statusFilter.value||undefined,bookingType:typeFilter.value||undefined,keyword:keyword.value||undefined})
async function loadBookings(){await run(async()=>bookings.value=await api.getMeetingBookings(query())||[])}
async function loadApprovals(){await run(async()=>{[rules.value,tasks.value]=await Promise.all([api.getMeetingApprovalRules(),api.getMeetingApprovalTasks({status:'PENDING'})]);rules.value=rules.value||[];tasks.value=tasks.value||[]})}
async function loadUsage(){await run(async()=>{[usages.value,logs.value]=await Promise.all([api.getMeetingUsageRecords({startDate:start.value,endDate:end.value}),api.getMeetingVerificationLogs({startDate:start.value,endDate:end.value})])})}
async function loadReport(){await run(async()=>{const p={startDate:start.value,endDate:end.value};[overview.value,utilization.value,serviceSales.value]=await Promise.all([api.getMeetingReportOverview(p),api.getMeetingRoomUtilization(p),api.getMeetingServiceSales(p)])})}
function switchTab(v){tab.value=v;if(v==='bookings')loadBookings();if(v==='approvals')loadApprovals();if(v==='verification')loadUsage();if(v==='reports')loadReport()}
function reset(v){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,v)}
function open(kind,item){modal.value=kind
  const defaults={room:{roomCode:'',name:'',location:'',capacity:20,description:'',openTime:'08:00',closeTime:'18:00',status:'ACTIVE'},equipment:{roomId:roomFilter.value||'',equipmentCode:'',name:'',quantity:1,description:'',status:'ACTIVE'},opening:{roomId:roomFilter.value||'',dayOfWeek:1,startTime:'08:00',endTime:'18:00',slotMinutes:30,status:'ACTIVE'},price:{roomId:roomFilter.value||'',ruleCode:'',name:'',startDate:'',endDate:'',dayOfWeek:'',startTime:'',endTime:'',minAttendees:1,maxAttendees:100,priceYuan:0,priority:0,status:'ACTIVE'},service:{serviceCode:'',name:'',serviceType:'EQUIPMENT',pricingUnit:'PER_EVENT',priceYuan:0,description:'',status:'ACTIVE'}}
  reset(item?{...item,priceYuan:item.priceCent!=null?item.priceCent/100:undefined}:defaults[kind])
}
async function save(){await run(async()=>{let data={...form};delete data.id;delete data.roomName;delete data.createdAt;delete data.updatedAt;delete data.equipmentCount;delete data.openingRuleCount;delete data.priceYuan
  for(const k of ['startDate','endDate','dayOfWeek','startTime','endTime'])if(data[k]==='')data[k]=null
  if(['equipment','opening','price'].includes(modal.value))data.roomId=Number(data.roomId)
  if(modal.value==='price')data.priceCent=Math.round(Number(form.priceYuan)*100)
  if(modal.value==='service')data.priceCent=Math.round(Number(form.priceYuan)*100)
  const names={room:['createMeetingRoom','updateMeetingRoom'],equipment:['createMeetingEquipment','updateMeetingEquipment'],opening:['createMeetingOpeningRule','updateMeetingOpeningRule'],price:['createMeetingPriceRule','updateMeetingPriceRule'],service:['createMeetingService','updateMeetingService']}[modal.value]
  form.id?await api[names[1]](form.id,data):await api[names[0]](data);modal.value='';await loadConfig()},'保存成功')}
async function decide(task,approved){const comment=prompt(approved?'审批意见（可选）':'请输入驳回原因')||'';if(!approved&&!comment)return;await run(async()=>{approved?await api.approveMeetingTask(task.taskId,{comment}):await api.rejectMeetingTask(task.taskId,{comment});await loadApprovals();await loadBookings()},approved?'审批已通过':'审批已驳回')}
async function saveRules(){await run(async()=>{await api.replaceMeetingApprovalRules({steps:rules.value.map((v,i)=>({approverUserId:Number(v.approverUserId),stepName:v.stepName||`第${i+1}级审批`}))});await loadApprovals()},'审批流程已发布新版本')}
function addRule(){rules.value.push({approverUserId:'',stepName:`第${rules.value.length+1}级审批`})}
async function consume(){await run(async()=>{await api.consumeMeetingVerification({code:verifyCode.value,deviceNo:deviceNo.value});verifyCode.value='';await loadUsage()},'核销成功，会议已开始使用')}
async function revoke(v){const reason=prompt('请输入撤销原因');if(!reason)return;await run(async()=>{await api.revokeMeetingVerification(v.verificationId,{reason});await loadUsage()},'核销已撤销')}
async function complete(v){if(!confirm(`确认会议“${v.meetingSubject}”已使用结束？`))return;await run(async()=>{await api.completeMeetingUsage(v.bookingId);await loadUsage()},'会议使用已完成')}
async function downloadCsv(){await run(async()=>{const blob=await api.exportMeetingBookingsCsv(query());download(blob,`会议预订台账_${start.value}_${end.value}.csv`)})}
function money(v){return `¥${(Number(v||0)/100).toFixed(2)}`};function date(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function dt(v){return v?String(v).replace('T',' ').slice(0,16):'-'};function status(v){return statusText[v]||v||'-'}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
onMounted(loadConfig)
</script>

<template><div class="meeting-page">
  <div class="toolbar"><div><h2>会议场地运营</h2><p>会议室配置、组合服务、多级审批、现场核销与经营报表统一工作台。</p></div><button :disabled="loading" @click="loadConfig">{{loading?'处理中…':'刷新基础数据'}}</button></div>
  <p v-if="error" class="error message">{{error}}</p><p v-if="notice" class="success message">{{notice}}</p>
  <div class="filters panel"><label>开始日期<input v-model="start" type="date"></label><label>结束日期<input v-model="end" type="date"></label><label>会议室<select v-model="roomFilter"><option value="">全部会议室</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label></div>
  <div class="content-tabs tabs"><button v-for="v in [['config','场地配置'],['bookings','预订台账'],['approvals','审批管理'],['verification','核销管理'],['reports','运营报表']]" :key="v[0]" :class="{active:tab===v[0]}" @click="switchTab(v[0])">{{v[1]}}</button></div>

  <section v-if="tab==='config'"><div class="config-nav"><button v-for="v in [['rooms','会议室'],['equipment','设备'],['openings','开放时段'],['prices','收费标准'],['services','配套服务']]" :key="v[0]" :class="{active:configTab===v[0]}" @click="configTab=v[0]">{{v[1]}}</button></div>
    <div class="toolbar"><div><h3>基础资料维护</h3><p>支持停启用、容量、设备、分时/规模收费及茶歇住宿配置。</p></div><button class="primary" @click="open({rooms:'room',equipment:'equipment',openings:'opening',prices:'price',services:'service'}[configTab])">新增</button></div>
    <div class="panel table-wrap"><table><thead><tr><th>编码/名称</th><th>归属/类型</th><th>规则详情</th><th>价格/数量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!configRows.length"><td colspan="6">暂无数据。</td></tr><tr v-for="v in configRows" :key="v.id"><td><b>{{v.name}}</b><small>{{v.roomCode||v.equipmentCode||v.ruleCode||v.serviceCode||`#${v.id}`}}</small></td><td>{{v.roomName||v.location||v.serviceType||'-'}}<small>{{v.pricingUnit||''}}</small></td><td><template v-if="configTab==='rooms'">容量 {{v.capacity}} 人 · {{v.openTime}}—{{v.closeTime}}</template><template v-else-if="configTab==='openings'">{{dayText[v.dayOfWeek]}} {{v.startTime}}—{{v.endTime}} · {{v.slotMinutes}}分钟</template><template v-else-if="configTab==='prices'">{{v.startDate||'不限'}}—{{v.endDate||'不限'}} · {{v.minAttendees||'-'}}~{{v.maxAttendees||'-'}}人</template><template v-else>{{v.description||'-'}}</template></td><td>{{configTab==='prices'||configTab==='services'?money(v.priceCent):v.quantity||'-'}}</td><td><span class="badge">{{status(v.status)}}</span></td><td><button @click="open({rooms:'room',equipment:'equipment',openings:'opening',prices:'price',services:'service'}[configTab],v)">编辑</button></td></tr></tbody></table></div>
  </section>

  <section v-if="tab==='bookings'"><div class="filters"><input v-model="keyword" placeholder="预订号/主题/联系人"><select v-model="typeFilter"><option value="">全部类型</option><option value="EXTERNAL">外部会议</option><option value="INTERNAL">内部会议</option></select><select v-model="statusFilter"><option value="">全部状态</option><option v-for="v in Object.keys(statusText).slice(0,10)" :key="v" :value="v">{{status(v)}}</option></select><button class="primary" @click="loadBookings">查询</button><button @click="downloadCsv">导出 CSV</button></div><div class="panel table-wrap"><table><thead><tr><th>预订/订单</th><th>会议主题</th><th>会议室/时段</th><th>联系人</th><th>金额</th><th>审批/使用</th></tr></thead><tbody><tr v-if="!bookings.length"><td colspan="6">所选条件暂无预订。</td></tr><tr v-for="v in bookings" :key="v.id"><td><b>{{v.bookingNo}}</b><small>{{v.orderNo||'未生成订单'}} · {{v.bookingType==='INTERNAL'?'内部':'外部'}}</small></td><td>{{v.meetingSubject}}<small>{{v.attendees}} 人</small></td><td>{{v.roomName}}<small>{{v.bookingDate}} {{v.startTime}}—{{v.endTime}}</small></td><td>{{v.contactName}}<small>{{v.contactMobile}}</small></td><td>{{money(v.totalAmountCent)}}<small>实付 {{money(v.paidAmountCent)}}</small></td><td><span class="badge">{{status(v.status)}}</span><small>{{status(v.approvalStatus)}} / {{status(v.usageStatus)}}</small></td></tr></tbody></table></div></section>

  <section v-if="tab==='approvals'"><div class="approval-grid"><div class="panel"><div class="toolbar"><div><h3>多级审批规则</h3><p>发布后生成新版本，不影响进行中的审批实例。</p></div><button @click="addRule">增加一级</button></div><div v-for="(v,i) in rules" :key="i" class="rule-row"><b>{{i+1}}</b><input v-model="v.stepName" placeholder="步骤名称"><input v-model="v.approverUserId" type="number" placeholder="审批人用户ID"><button class="danger" @click="rules.splice(i,1)">移除</button></div><button class="primary" @click="saveRules">发布审批流程</button></div><div class="panel table-wrap"><h3>我的待审批任务</h3><table><thead><tr><th>会议</th><th>审批步骤</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-if="!tasks.length"><td colspan="4">当前没有待审批任务。</td></tr><tr v-for="v in tasks" :key="v.taskId"><td>{{v.meetingSubject}}<small>{{v.bookingNo}}</small></td><td>第 {{v.stepNo}} 级 · {{v.stepName}}</td><td>{{dt(v.createdAt)}}</td><td><button class="primary" @click="decide(v,true)">通过</button> <button class="danger" @click="decide(v,false)">驳回</button></td></tr></tbody></table></div></div></section>

  <section v-if="tab==='verification'"><div class="verify panel"><div><h3>现场扫码核销</h3><p>扫描用户会议预约二维码，重复核销自动拦截。</p></div><label>设备号<input v-model="deviceNo"></label><label>核销码<input v-model.trim="verifyCode" placeholder="BFHV-…" @keyup.enter="consume"></label><button class="primary" :disabled="!verifyCode" @click="consume">核销入场</button></div><div class="panel table-wrap"><h3>会议使用记录</h3><table><thead><tr><th>预订</th><th>会议室/时段</th><th>人数</th><th>入场/结束</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="!usages.length"><td colspan="6">暂无使用记录。</td></tr><tr v-for="v in usages" :key="v.bookingId"><td>{{v.meetingSubject}}<small>{{v.bookingNo}}</small></td><td>{{v.roomName}}<small>{{v.bookingDate}} {{v.startTime}}—{{v.endTime}}</small></td><td>{{v.attendees}}</td><td>{{dt(v.usageStartedAt)}}<small>{{dt(v.usageEndedAt)}}</small></td><td><span class="badge">{{status(v.usageStatus)}}</span></td><td><button v-if="v.usageStatus==='CHECKED_IN'" class="primary" @click="complete(v)">结束使用</button> <button v-if="v.usageStatus==='CHECKED_IN'" class="danger" @click="revoke(v)">撤销核销</button></td></tr></tbody></table></div><div class="panel table-wrap"><h3>核销操作日志</h3><table><thead><tr><th>预订</th><th>动作</th><th>操作人/设备</th><th>状态变化</th><th>时间</th></tr></thead><tbody><tr v-for="v in logs" :key="v.id"><td>{{v.bookingNo}}</td><td>{{v.action}}</td><td>{{v.operatorName}}<small>{{v.deviceNo||'-'}}</small></td><td>{{v.statusBefore}} → {{v.statusAfter}}</td><td>{{dt(v.createdAt)}}</td></tr></tbody></table></div></section>

  <section v-if="tab==='reports'"><div class="toolbar"><div><h3>会议运营分析</h3><p>统计口径按预订日期，可查询最长 366 天。</p></div><div><button class="primary" @click="loadReport">生成报表</button> <button @click="downloadCsv">导出台账</button></div></div><div class="report-stats"><article v-for="v in cards" :key="v[0]"><span>{{v[0]}}</span><strong>{{v[1]}}</strong><small>{{v[2]}}</small></article></div><div class="report-grid"><div class="panel table-wrap"><h3>会议室利用率</h3><table><thead><tr><th>会议室</th><th>预订数</th><th>可用分钟</th><th>占用分钟</th><th>利用率</th></tr></thead><tbody><tr v-for="v in utilization" :key="v.roomId"><td>{{v.roomName}}<small>{{v.roomCode}}</small></td><td>{{v.bookingCount}}</td><td>{{v.capacityMinutes}}</td><td>{{v.occupiedMinutes}}</td><td><b>{{v.utilizationRate}}%</b></td></tr></tbody></table></div><div class="panel table-wrap"><h3>配套服务销售</h3><table><thead><tr><th>服务</th><th>类型</th><th>预订数</th><th>数量</th><th>销售额</th></tr></thead><tbody><tr v-for="v in serviceSales" :key="v.serviceId"><td>{{v.serviceName}}<small>{{v.serviceCode}}</small></td><td>{{v.serviceType}}</td><td>{{v.bookingCount}}</td><td>{{v.quantity}}</td><td>{{money(v.salesAmountCent)}}</td></tr></tbody></table></div></div></section>

  <div v-if="modal" class="modal-backdrop" @click.self="modal='' "><section class="modal panel"><div class="toolbar"><h3>维护{{ {room:'会议室',equipment:'设备',opening:'开放时段',price:'收费规则',service:'配套服务'}[modal] }}</h3><button @click="modal=''">×</button></div><div class="form-grid">
    <template v-if="modal==='room'"><label>会议室编码<input v-model.trim="form.roomCode"></label><label>名称<input v-model.trim="form.name"></label><label>位置<input v-model.trim="form.location"></label><label>容纳人数<input v-model.number="form.capacity" type="number"></label><label>开放时间<input v-model="form.openTime" type="time"></label><label>关闭时间<input v-model="form.closeTime" type="time"></label></template>
    <template v-if="modal==='equipment'"><label>会议室<select v-model="form.roomId"><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>设备编码<input v-model.trim="form.equipmentCode"></label><label>设备名称<input v-model.trim="form.name"></label><label>数量<input v-model.number="form.quantity" type="number"></label></template>
    <template v-if="modal==='opening'"><label>会议室<select v-model="form.roomId"><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>星期<select v-model.number="form.dayOfWeek"><option v-for="i in 7" :key="i" :value="i">{{dayText[i]}}</option></select></label><label>开始<input v-model="form.startTime" type="time"></label><label>结束<input v-model="form.endTime" type="time"></label><label>时段分钟<input v-model.number="form.slotMinutes" type="number"></label></template>
    <template v-if="modal==='price'"><label>会议室<select v-model="form.roomId"><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>规则编码<input v-model.trim="form.ruleCode"></label><label>规则名称<input v-model.trim="form.name"></label><label>价格（元）<input v-model.number="form.priceYuan" type="number" step="0.01"></label><label>开始日期<input v-model="form.startDate" type="date"></label><label>结束日期<input v-model="form.endDate" type="date"></label><label>星期<select v-model="form.dayOfWeek"><option value="">每天</option><option v-for="i in 7" :key="i" :value="i">{{dayText[i]}}</option></select></label><label>开始时间<input v-model="form.startTime" type="time"></label><label>结束时间<input v-model="form.endTime" type="time"></label><label>最少人数<input v-model.number="form.minAttendees" type="number"></label><label>最多人数<input v-model.number="form.maxAttendees" type="number"></label><label>优先级<input v-model.number="form.priority" type="number"></label></template>
    <template v-if="modal==='service'"><label>服务编码<input v-model.trim="form.serviceCode"></label><label>名称<input v-model.trim="form.name"></label><label>类型<select v-model="form.serviceType"><option value="EQUIPMENT">设备租赁</option><option value="TEA_BREAK">茶歇</option><option value="ACCOMMODATION">住宿</option></select></label><label>计价单位<select v-model="form.pricingUnit"><option value="PER_EVENT">每场</option><option value="PER_PERSON">每人</option><option value="PER_HOUR">每小时</option><option value="PER_DAY">每天</option></select></label><label>价格（元）<input v-model.number="form.priceYuan" type="number" step="0.01"></label></template>
    <label v-if="!['opening','price'].includes(modal)" class="wide">说明<textarea v-model="form.description" rows="3"></textarea></label><label>状态<select v-model="form.status"><option value="ACTIVE">启用</option><option value="INACTIVE">停用</option></select></label></div><div class="modal-actions"><button @click="modal=''">取消</button><button class="primary" @click="save">保存</button></div></section></div>
</div></template>

<style scoped>
.message{margin:0 0 12px}.filters{display:flex;align-items:end;gap:12px;margin-bottom:16px}.filters label{display:grid;gap:5px;font-size:12px;color:#607167}.filters input,.filters select,.form-grid input,.form-grid select,.form-grid textarea,.rule-row input,.verify input{padding:9px;border:1px solid #dce6e0;border-radius:8px;background:#fff}.tabs{overflow-x:auto}.config-nav{display:flex;gap:8px;margin:14px 0}.config-nav button.active{color:#fff;background:#176b58}.approval-grid,.report-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:16px}.rule-row{display:grid;grid-template-columns:30px 1fr 1fr auto;gap:8px;align-items:center;margin-bottom:9px}.verify{display:grid;grid-template-columns:1.5fr 1fr 1fr auto;gap:14px;align-items:end;margin-bottom:16px}.verify label,.form-grid label{display:grid;gap:6px;font-size:12px;color:#607167}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-grid .wide{grid-column:1/-1}.modal{width:min(760px,100%)}h3{margin-top:0}.table-wrap h3{padding:15px 15px 0}.report-stats{grid-template-columns:repeat(5,minmax(0,1fr))}@media(max-width:1000px){.approval-grid,.report-grid{grid-template-columns:1fr}.report-stats{grid-template-columns:repeat(2,1fr)}.verify{grid-template-columns:1fr 1fr}}@media(max-width:720px){.filters,.verify{align-items:stretch;flex-direction:column;display:flex}.form-grid,.rule-row{grid-template-columns:1fr}.report-stats{grid-template-columns:1fr}}
</style>
